-- 027: realness weights rebalanced after the first backfill (2026-10-01): mx 0.20, contact 0.20, age_90d 0.15.
ALTER TABLE businesses UPDATE estimated_realness = toFloat32(if(estimated_junk != '', 0, least(1.0, if(notEmpty(dns_mx), 0.2, 0) + if(dns_dmarc != '', 0.05, 0) + if((notEmpty(http_emails) OR http_phone != ''), 0.2, 0) + if(http_address != '', 0.05, 0) + if(http_company_id != '', 0.1, 0) + if(http_schema_type IN ('Organization', 'LocalBusiness', 'Corporation', 'Store', 'OnlineStore', 'ProfessionalService', 'Restaurant', 'MedicalBusiness', 'FinancialService', 'EducationalOrganization', 'TravelAgency', 'RealEstateAgent', 'LegalService', 'HomeAndConstructionBusiness', 'AutoDealer', 'AutomotiveBusiness', 'SportsActivityLocation', 'HealthAndBeautyBusiness', 'FoodEstablishment', 'LodgingBusiness', 'Dentist', 'Physician', 'Hotel'), 0.05, 0) + if(ctl_first_seen_at < now() - INTERVAL 90 DAY, 0.15, 0) + if((coalesce(shop_product_count, 0) > 0 OR coalesce(hr_job_count, 0) > 0), 0.1, 0) + if((tranco_rank IS NOT NULL OR majestic_rank IS NOT NULL), 0.1, 0) + if(notEmpty(http_social_links), 0.05, 0) + if(verified_at IS NOT NULL, 0.1, 0)))), estimated_realness_evidence = if(estimated_junk != '', '', arrayStringConcat(arrayFilter(x -> x != '', [if(notEmpty(dns_mx), 'mx', ''), if(dns_dmarc != '', 'dmarc', ''), if((notEmpty(http_emails) OR http_phone != ''), 'contact', ''), if(http_address != '', 'address', ''), if(http_company_id != '', 'company_id', ''), if(http_schema_type IN ('Organization', 'LocalBusiness', 'Corporation', 'Store', 'OnlineStore', 'ProfessionalService', 'Restaurant', 'MedicalBusiness', 'FinancialService', 'EducationalOrganization', 'TravelAgency', 'RealEstateAgent', 'LegalService', 'HomeAndConstructionBusiness', 'AutoDealer', 'AutomotiveBusiness', 'SportsActivityLocation', 'HealthAndBeautyBusiness', 'FoodEstablishment', 'LodgingBusiness', 'Dentist', 'Physician', 'Hotel'), 'schema_org', ''), if(ctl_first_seen_at < now() - INTERVAL 90 DAY, 'age_90d', ''), if((coalesce(shop_product_count, 0) > 0 OR coalesce(hr_job_count, 0) > 0), 'activity', ''), if((tranco_rank IS NOT NULL OR majestic_rank IS NOT NULL), 'traffic', ''), if(notEmpty(http_social_links), 'social', ''), if(verified_at IS NOT NULL, 'registry', '')]), '|')) WHERE 1;
